/// The cargo argv [`verify`] runs — a FUNCTION so a test can read what is sent.
///
/// `--all-targets` is the load-bearing word and it is invisible from anywhere else: `verify` shells
/// out, so nothing else in this crate can observe whether the migration's own verification compiles a
/// `#[cfg(test)]` module. It did not, for the whole of `src-tauri`.
pub(crate) fn verify_argv(pkg: &str) -> Vec<String> {
    ["check", "-p", pkg, "--all-targets"].iter().map(|s| (*s).to_string()).collect()
}
